        uint256 currentRate = rTotal / tTotal;
        console.log("Current rate:", currentRate);
        console.log("tTotal:", tTotal);
        console.log("rTotal:", rTotal);

        // We want a smaller amount to avoid overflow
        uint256 desiredTokens = 100 * 10**18; // 100 tokens
        // Calculate reflection amount safely
        uint256 reflectionAmount;
        unchecked {
            reflectionAmount = desiredTokens * currentRate;
        }
        console.log("Reflection amount needed:", reflectionAmount);

        // Set attacker's _rOwned balance
        // _rOwned mapping is at slot 0, key is attacker address
        bytes32 mappingSlot = keccak256(abi.encode(uint256(uint160(attacker)), uint256(0)));
